// Raise the generated Android project's target/compile SDK to the level Play
// requires. Runs AUTOMATICALLY after `npm run play:twa:init` (npm's `post<script>`
// hook) and before `npm run play:twa:build`.
//
// WHY THIS EXISTS: `/app/` is generated by @bubblewrap/cli and is gitignored, so
// nothing in it survives a re-init and nothing in it can be fixed by a commit.
// Bubblewrap 1.24.1 — the newest published version — still writes
// `targetSdkVersion 35`, while Google Play requires 36 (Android 16) for updates
// from 31 Aug 2026. Hand-editing app/build.gradle works exactly once: the next
// `play:twa:init` silently reverts it, and the regression is invisible until Play
// rejects the upload.
//
// So the bump is applied by a script instead of by memory. The required level
// comes from PLAY_MIN_TARGET_SDK in @rushpoint/shared, which is also what
// `npm run play:store:check` enforces — one number, one place.
//
//   node scripts/patch-twa-target-sdk.mjs [--check]
//
// `--check` reports without writing (exit 1 if a bump is needed).
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const repo = dirname(dirname(fileURLToPath(import.meta.url)));
const GRADLE = join(repo, 'app', 'build.gradle');
const checkOnly = process.argv.includes('--check');

// Read the required level straight from the shared source so this can never
// disagree with the gate. Parsed, not imported: this is a plain .mjs script and
// shared is TypeScript that may not be built yet.
const sharedSrc = readFileSync(join(repo, 'packages/shared/src/playStore.ts'), 'utf8');
const required = Number((/export const PLAY_MIN_TARGET_SDK = (\d+)/.exec(sharedSrc) || [])[1]);
if (!Number.isFinite(required)) {
  console.error('✗ could not read PLAY_MIN_TARGET_SDK from packages/shared/src/playStore.ts');
  process.exit(1);
}

if (!existsSync(GRADLE)) {
  // Not an error: the Android project only exists after `play:twa:init`, and this
  // script runs on machines that never build the APK.
  console.log(`· app/build.gradle not present — skipping (run "npm run play:twa:init" first).`);
  process.exit(0);
}

const before = readFileSync(GRADLE, 'utf8');
let after = before;
const changes = [];

// targetSdkVersion — the one Play actually gates on.
after = after.replace(/(\btargetSdk(?:Version)?\s*=?\s*)(\d+)/, (m, head, n) => {
  const cur = Number(n);
  if (cur >= required) return m;
  changes.push(`targetSdkVersion ${cur} → ${required}`);
  return `${head}${required}`;
});

// compileSdkVersion must be >= targetSdkVersion or the build fails outright.
after = after.replace(/(\bcompileSdk(?:Version)?\s*=?\s*)(\d+)/, (m, head, n) => {
  const cur = Number(n);
  if (cur >= required) return m;
  changes.push(`compileSdkVersion ${cur} → ${required}`);
  return `${head}${required}`;
});

if (changes.length === 0) {
  console.log(`✓ Android project already targets API ${required}.`);
  process.exit(0);
}

if (checkOnly) {
  console.error(`✗ app/build.gradle needs: ${changes.join(', ')}`);
  console.error('  Run: node scripts/patch-twa-target-sdk.mjs');
  process.exit(1);
}

writeFileSync(GRADLE, after);
console.log(`✓ Patched app/build.gradle — ${changes.join(', ')}`);
